-- 16. 온유 서초 네일 스튜디오: 일반 3, 모델 0; OSM node/368725613
INSERT INTO SHOP (SHOP_ID, CATEGORY_ID, LOGIN_ID, PASSWORD_HASH, NAME, REGION_CODE, ADDRESS, ADDRESS_DETAIL,
    LATITUDE, LONGITUDE, PHONE, DESCRIPTION, NOTICE, STATUS, CREATED_AT, UPDATED_AT)
SELECT SEQ_SHOP.NEXTVAL, 1, 'demo164_s16', 'CHANGE_ME', '온유 서초 네일 스튜디오', '11650', '서울특별시 서초구 남부순환로 2423', '시연용 가상공간',
    37.4817930, 127.0153710, '02-0000-0000', '서초구에서 편안하게 머무는 온유 서초 네일 스튜디오입니다. 취향과 컨디션을 충분히 상담하고 한 분씩 정성껏 관리합니다. 시연을 위해 만든 가상 매장입니다.',
