SELECT SEQ_SHOP.NEXTVAL, 4, 'demo164_s19', 'CHANGE_ME', '온유 송파 피부 관리 스튜디오', '11710', '서울특별시 송파구 오금로49길 18', '시연용 가상공간',
    37.4971396, 127.1386359, '02-0000-0000', '송파구에서 편안하게 머무는 온유 송파 피부 관리 스튜디오입니다. 취향과 컨디션을 충분히 상담하고 한 분씩 정성껏 관리합니다. 시연을 위해 만든 가상 매장입니다.',
    '시연용 가상 매장입니다. 주소는 지도 시연용이며 실제 입점 정보가 아닙니다. 표시된 전화번호는 연결되지 않는 더미입니다.', 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM SHOP WHERE LOGIN_ID = 'demo164_s19');
INSERT INTO TREATMENT (TREATMENT_ID, SHOP_ID, NAME, DESCRIPTION, REGULAR_PRICE, PRICE, LAST_MINUTE_PRICE,
    DURATION_MINUTES, TREATMENT_TYPE, MODEL_CONDITION, PREPARATION_NOTES, PHOTO_NOTICE, STATUS, CREATED_AT, UPDATED_AT)
SELECT SEQ_TREATMENT.NEXTVAL, (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s19'), '기본 모공 클렌징', '피부 상태를 상담한 뒤 클렌징과 해당 관리, 보습 마무리를 진행합니다. 자극이 느껴지면 즉시 알려 주세요.', 77000, 69300, 58900,
    90, 'NORMAL', NULL, '예약 시간 10분 전 도착해 주세요. 기존 시술 이력과 알레르기 등 상담할 내용을 미리 알려 주세요.', NULL, 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM TREATMENT WHERE SHOP_ID = (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s19') AND NAME = '기본 모공 클렌징');
