-- 39. 고운 관악 피부 관리 스튜디오: 일반 2, 모델 1; OSM node/368603306
INSERT INTO SHOP (SHOP_ID, CATEGORY_ID, LOGIN_ID, PASSWORD_HASH, NAME, REGION_CODE, ADDRESS, ADDRESS_DETAIL,
    LATITUDE, LONGITUDE, PHONE, DESCRIPTION, NOTICE, STATUS, CREATED_AT, UPDATED_AT)
SELECT SEQ_SHOP.NEXTVAL, 4, 'demo164_s39', 'CHANGE_ME', '고운 관악 피부 관리 스튜디오', '11620', '서울특별시 관악구 문성로25길 12-15', '시연용 가상공간',
    37.4794374, 126.9264078, '02-0000-0000', '관악구에서 편안하게 머무는 고운 관악 피부 관리 스튜디오입니다. 취향과 컨디션을 충분히 상담하고 한 분씩 정성껏 관리합니다. 시연을 위해 만든 가상 매장입니다.',
    '시연용 가상 매장입니다. 주소는 지도 시연용이며 실제 입점 정보가 아닙니다. 표시된 전화번호는 연결되지 않는 더미입니다.', 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM SHOP WHERE LOGIN_ID = 'demo164_s39');
